import{_ as r,C as n,o as a,c as o,E as i,a2 as s}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"Industry Architecture Weekly 001 — The Enterprise Agent Governance Control Plane Is Taking Shape","description":"","frontmatter":{"title":"Industry Architecture Weekly 001 — The Enterprise Agent Governance Control Plane Is Taking Shape","date":"2026-08-02","column":"industry-architecture","category":"weekly","summary":"Workday, ServiceNow, and Microsoft are converging on a common enterprise Agent governance control plane: discover and register assets, assign owners, manage authority and lifecycle, observe runtime risk, and measure cost and value.","sources":["Workday Agent System of Record","ServiceNow AI Control Tower","Microsoft Agent 365"],"outline":"deep","cover":"/assets/covers/enterprise-agent-governance-control-plane-cover-v2.jpg"},"headers":[],"relativePath":"en/industry/2026-08-02-enterprise-agent-governance-control-plane.md","filePath":"en/industry/2026-08-02-enterprise-agent-governance-control-plane.md","lastUpdated":1787407830000}'),l={name:"en/industry/2026-08-02-enterprise-agent-governance-control-plane.md"};function c(d,e,p,h,g,m){const t=n("ArticleCover");return a(),o("div",null,[i(t,{image:"/assets/covers/enterprise-agent-governance-control-plane-cover-v2.jpg",kicker:"Industry Architecture · Weekly 001",title:"The Enterprise Agent Governance Control Plane Is Taking Shape",summary:"Workday, ServiceNow, and Microsoft converge on discovery, registry, governance, security, observation, and value measurement.",version:"IW001",status:"Published 2026-08-02",languageHref:"/zh/industry/2026-08-02-enterprise-agent-governance-control-plane",languageLabel:"简体中文"}),e[0]||(e[0]=s(`<h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>The strongest industry architecture signal this week is not another improvement in model reasoning. It is the emergence of an enterprise control plane above models, Agent frameworks, and business applications.</p><p>Workday places AI Agents inside a blended-workforce System of Record. ServiceNow expands AI Control Tower across five dimensions—Discover, Observe, Govern, Secure, and Measure. Microsoft Agent 365 combines Agent Registry, Entra, Purview, and lifecycle actions to manage Agents across environments.</p><p>This report’s judgment is:</p><blockquote><p>Enterprise Agent governance is moving from scattered product settings into a distinct control plane. Its primary object is not a prompt, but an organizational asset that can be discovered, owned, authorized, observed, blocked, retired, and measured.</p></blockquote><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>Three groups of official materials were selected:</p><ol><li><strong>Workday Agent System of Record (ASOR):</strong> unified inventory, lifecycle, accountability, permissions, interaction metering, and value analytics.</li><li><strong>ServiceNow AI Control Tower:</strong> cross-platform AI asset governance across Discover, Observe, Govern, Secure, and Measure.</li><li><strong>Microsoft Agent 365:</strong> Agent Registry, registry sync, ownership, access governance, activation, blocking, and retirement.</li></ol><p>These sources support analysis of publicly described product architecture. Vendor claims about scale, market coverage, or business outcomes remain vendor claims unless independently verified.</p><h2 id="weekly-highlights" tabindex="-1">Weekly Highlights <a class="header-anchor" href="#weekly-highlights" aria-label="Permalink to &quot;Weekly Highlights&quot;">​</a></h2><h3 id="_1-agent-registry-is-becoming-the-common-starting-point" tabindex="-1">1. Agent Registry is becoming the common starting point <a class="header-anchor" href="#_1-agent-registry-is-becoming-the-common-starting-point" aria-label="Permalink to &quot;1. Agent Registry is becoming the common starting point&quot;">​</a></h3><p>All three systems first address a basic question: which Agents exist inside the organization?</p><ul><li>Workday ASOR registers Workday, customer-built, and third-party Agents;</li><li>ServiceNow discovers Agents, models, identities, workflows, MCP servers, and other AI assets;</li><li>Microsoft Agent Registry can synchronize external Agent environments into one governance view.</li></ul><p>The first step in enterprise Agent governance is therefore not orchestration. It is asset discovery and identity establishment.</p><h3 id="_2-ownership-and-lifecycle-are-becoming-formal-governance-data" tabindex="-1">2. Ownership and lifecycle are becoming formal governance data <a class="header-anchor" href="#_2-ownership-and-lifecycle-are-becoming-formal-governance-data" aria-label="Permalink to &quot;2. Ownership and lifecycle are becoming formal governance data&quot;">​</a></h3><p>Workday describes a lifecycle of register, configure, activate, and deactivate, while emphasizing responsibility and accountability. Microsoft supports ownership assignment, installation, activation, blocking, reassignment, and deletion. ServiceNow places AI asset owners, stewards, and risk teams inside a shared governance process.</p><p>Agents are beginning to resemble service accounts, applications, and organizational positions: persistent assets with governed state.</p><h3 id="_3-runtime-observation-is-replacing-one-time-review" tabindex="-1">3. Runtime observation is replacing one-time review <a class="header-anchor" href="#_3-runtime-observation-is-replacing-one-time-review" aria-label="Permalink to &quot;3. Runtime observation is replacing one-time review&quot;">​</a></h3><p>ServiceNow explicitly includes continuous observation, live metrics, behavior traces, and alerts. Workday’s Agent Gateway manages and meters interactions. Microsoft extends identity, data, and threat protection to Agents.</p><p>Governance is shifting from pre-deployment approval toward pre-deployment validation plus continuous runtime judgment.</p><h2 id="cross-analysis" tabindex="-1">Cross Analysis <a class="header-anchor" href="#cross-analysis" aria-label="Permalink to &quot;Cross Analysis&quot;">​</a></h2><h3 id="control-plane-capability-matrix" tabindex="-1">Control-plane capability matrix <a class="header-anchor" href="#control-plane-capability-matrix" aria-label="Permalink to &quot;Control-plane capability matrix&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Workday ASOR</th><th>ServiceNow AI Control Tower</th><th>Microsoft Agent 365</th></tr></thead><tbody><tr><td>Unified inventory / registry</td><td>First- and third-party Agents</td><td>Agents, models, identities, workflows, MCP assets</td><td>First-party and external Agent Registry</td></tr><tr><td>Ownership / accountability</td><td>Role, responsibility, accountability</td><td>AI asset owners, stewards, risk processes</td><td>Owner assignment and reassignment</td></tr><tr><td>Lifecycle</td><td>Register, configure, activate, deactivate</td><td>Discover, assess, govern, remediate</td><td>Install, activate, block, delete</td></tr><tr><td>Identity and authority</td><td>Precise identity and permissions; Agent Gateway</td><td>Identity access governance, least privilege, kill switch</td><td>Entra identities, access packages, policy</td></tr><tr><td>Runtime observation</td><td>Interaction metering and analytics</td><td>Runtime traces, metrics, alerts, behavior observation</td><td>Agent Map plus security and risk monitoring</td></tr><tr><td>Cost and value</td><td>Cost, impact, dynamic ROI</td><td>Cost tracking and ROI dashboards</td><td>Stronger emphasis on governance, security, compliance</td></tr><tr><td>Primary enterprise anchor</td><td>HCM, finance, blended workforce</td><td>IT governance, CMDB, workflow</td><td>Microsoft 365, Entra, Purview</td></tr></tbody></table><p><strong>Note:</strong> This table is synthesized from official capability descriptions. It is not an independent benchmark and does not imply equal maturity across columns.</p><h3 id="shared-control-plane-structure" tabindex="-1">Shared control-plane structure <a class="header-anchor" href="#shared-control-plane-structure" aria-label="Permalink to &quot;Shared control-plane structure&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agents, models, and runtime environments</span></span>
<span class="line"><span>                 ↓</span></span>
<span class="line"><span>         Discover / Register</span></span>
<span class="line"><span>                 ↓</span></span>
<span class="line"><span>    Identity + Owner + Position</span></span>
<span class="line"><span>                 ↓</span></span>
<span class="line"><span>    Policy + Access + Lifecycle</span></span>
<span class="line"><span>                 ↓</span></span>
<span class="line"><span>   Observe + Risk + Cost + Value</span></span>
<span class="line"><span>                 ↓</span></span>
<span class="line"><span> Block / Retire / Improve / Audit</span></span></code></pre></div><p><em>Diagram: joinwell52 Research Center synthesis from official materials.</em></p><h3 id="a-control-plane-is-not-a-work-runtime" tabindex="-1">A control plane is not a work runtime <a class="header-anchor" href="#a-control-plane-is-not-a-work-runtime" aria-label="Permalink to &quot;A control plane is not a work runtime&quot;">​</a></h3><p>The control plane answers:</p><ul><li>Which Agents exist?</li><li>Who owns them?</li><li>What authority do they have?</li><li>Are they compliant?</li><li>What are their current risk, cost, and value states?</li><li>Should they be activated, blocked, or retired?</li></ul><p>It does not fully explain how a WorkOrder is decomposed, executed, recovered, evidenced, and completed. The control plane and work runtime should therefore be modeled separately and connected through a stable contract.</p><h2 id="new-architecture-judgment" tabindex="-1">New Architecture Judgment <a class="header-anchor" href="#new-architecture-judgment" aria-label="Permalink to &quot;New Architecture Judgment&quot;">​</a></h2><p>Four judgments emerge this week:</p><ol><li><strong>Agent Registry will become enterprise AI infrastructure.</strong> Cross-platform governance is impossible without an authoritative inventory.</li><li><strong>Owner is the entry point to the governance chain.</strong> Ownership connects approval, access, risk response, cost, and retirement responsibility.</li><li><strong>Identity and authority must remain independent of model provider.</strong> Models and runtimes may change while organizational identity persists.</li><li><strong>Continuous observation will become a formal governance condition.</strong> Static compliance records cannot replace runtime traces and behavioral state.</li></ol><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>This report does not modify TMPA publications. As research input, it reinforces the need for traceable references among Profile, Authority, Lifecycle, Event, Integrity, and Governance Judgment.</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>A minimum Digital Employee control plane requires Registry, Position and Owner, Authority Policy, Lifecycle, provider and tool bindings, runtime health, cost/value/evaluation, audit, and remediation actions.</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu already exposes substantial work-runtime facts but lacks a distinct control plane. The prudent sequence is to build a read-only Registry projection first, then add ownership, lifecycle, authority, and health remediation without rewriting the existing execution chain.</p><h2 id="next-week-research" tabindex="-1">Next Week Research <a class="header-anchor" href="#next-week-research" aria-label="Permalink to &quot;Next Week Research&quot;">​</a></h2><ol><li>Compare SAP, Oracle, and Salesforce Agent builders and runtime governance.</li><li>Define the minimum contract between control plane and runtime.</li><li>Compare kill switches, human escalation, and recovery policies.</li><li>Test whether SMEs need a full Control Tower or a minimal governance plane.</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Workday, <strong>Agent System of Record</strong>: <a href="https://www.workday.com/en-us/artificial-intelligence/agent-system-of-record.html" target="_blank" rel="noreferrer">https://www.workday.com/en-us/artificial-intelligence/agent-system-of-record.html</a></li><li>Workday, <strong>The Workday Agent System of Record Is Now Generally Available</strong>: <a href="https://blog.workday.com/en-us/managing-ai-powered-future-of-work.html" target="_blank" rel="noreferrer">https://blog.workday.com/en-us/managing-ai-powered-future-of-work.html</a></li><li>Workday, <strong>What are AI agents?</strong>: <a href="https://www.workday.com/en-us/topics/ai/ai-agents.html" target="_blank" rel="noreferrer">https://www.workday.com/en-us/topics/ai/ai-agents.html</a></li><li>ServiceNow, <strong>AI Control Tower</strong>: <a href="https://www.servicenow.com/products/ai-control-tower.html" target="_blank" rel="noreferrer">https://www.servicenow.com/products/ai-control-tower.html</a></li><li>ServiceNow, <strong>AI Control Tower expands across the enterprise</strong>: <a href="https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-expands-AI-Control-Tower-to-discover-observe-govern-secure-and-measure-AI-deployed-across-any-system-in-the-enterprise/default.aspx" target="_blank" rel="noreferrer">https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-expands-AI-Control-Tower-to-discover-observe-govern-secure-and-measure-AI-deployed-across-any-system-in-the-enterprise/default.aspx</a></li><li>Microsoft Learn, <strong>Microsoft Agent 365 overview</strong>: <a href="https://learn.microsoft.com/en-us/microsoft-agent-365/overview" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-agent-365/overview</a></li><li>Microsoft Learn, <strong>Registry sync in the Microsoft 365 agent registry</strong>: <a href="https://learn.microsoft.com/en-us/microsoft-agent-365/admin/agent-registry" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-agent-365/admin/agent-registry</a></li><li>Microsoft Learn, <strong>Govern agents using Agent 365</strong>: <a href="https://learn.microsoft.com/en-us/training/modules/agent-365-govern/" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/training/modules/agent-365-govern/</a></li></ol>`,45))])}const v=r(l,[["render",c]]);export{y as __pageData,v as default};
